"""Original, beginner-friendly course content. No network or API keys required."""

def lesson(id, title, minutes, body, code='', language='text'):
    return dict(id=id, title=title, minutes=minutes, body=body, code=code, language=language)

def question(prompt, options, answer, explanation):
    return dict(prompt=prompt, options=options, answer=answer, explanation=explanation)

